<?php $edit = $sectionData['edit'] ?? null; ?>
<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">People</span><h2><?= $edit ? 'Review customer profile' : 'Customer directory' ?></h2><p>Customer accounts are created through public registration. You can update contact details or deactivate access; passwords are never available here.</p></div></div>
  <?php if ($edit): ?><form class="admin-form-card admin-compact-form" method="post" action="<?= $this->escape(appUrl('/admin/customers/save')) ?>">
    <input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) $edit['id'] ?>">
    <div class="form-grid"><div class="field"><label for="customer-name">Full name *</label><input id="customer-name" name="name" maxlength="150" value="<?= $this->escape($edit['name']) ?>" required></div><div class="field"><label for="customer-email">Email address *</label><input id="customer-email" name="email" type="email" maxlength="190" value="<?= $this->escape($edit['email']) ?>" required></div></div>
    <div class="form-grid"><div class="field"><label for="customer-status">Account status</label><select id="customer-status" name="status"><option value="active" <?= $edit['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $edit['status'] !== 'active' ? 'selected' : '' ?>>Inactive</option></select><small>Inactive accounts cannot sign in.</small></div><div class="field"><span class="admin-field-label">Access role</span><div class="admin-readonly-value">Customer <small>Staff roles are managed separately by a super administrator.</small></div></div></div>
    <div class="admin-form-footer"><button class="button" type="submit">Save customer</button><a class="button button-ghost" href="<?= $this->escape(appUrl('/admin/customers')) ?>">Cancel</a></div>
  </form><?php endif ?>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Customer accounts</span><h2>Registered customers <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div><form class="admin-search" method="get" action="<?= $this->escape(appUrl('/admin/customers')) ?>"><label class="sr-only" for="customer-search">Search customers</label><input id="customer-search" name="q" value="<?= $this->escape($sectionData['query']) ?>" placeholder="Search name or email"><button class="button button-small" type="submit">Search</button></form></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No customer accounts match this search.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>Joined</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td><strong><?= $this->escape($record['name']) ?></strong><small class="table-subtext"><?= $this->escape($record['email']) ?></small></td><td><?= $this->escape(date('M j, Y', strtotime($record['created_at']))) ?></td><td><span class="status-badge status-<?= $this->escape($record['status']) ?>"><?= $this->escape(ucfirst($record['status'])) ?></span></td><td><a class="admin-icon-link" aria-label="Manage <?= $this->escape($record['name']) ?>" href="<?= $this->escape(appUrl('/admin/customers?id=' . (int) $record['id'])) ?>"><i data-lucide="pencil"></i></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
